eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   aboutData: () => (/* binding */ aboutData)\n/* harmony export */ });\nconst aboutData = {\n    hero: {\n        eyebrow: \"ABOUT ĀROHANA\",\n        headline: \"THE ROAD TO ĀROHANA WAS ANYTHING BUT STRAIGHT.\",\n        leadParagraph: \"I built it after spending years inside businesses — learning what makes them work, what makes them struggle, and what people see only after they become responsible for the whole thing.\",\n        extendedCopy: \"Today, Ārohana brings together that experience with strategy, communication, creativity and execution — for businesses that are serious about what they are building.\",\n        image: \"/images/about/madhura-portrait.jpg\",\n        mountainImage: \"/assets/about-mountain.png\"\n    },\n    philosophy: {\n        title: \"Philosophy\",\n        statement: \"We believe that communication and commercial strategy are inseparable. Effective design and digital positioning should stem directly from operations and margin realities.\",\n        subtext: \"We reject the agency echo chamber where vanity design wins awards while business owners struggle with unit economics and operational leakages.\"\n    },\n    milestones: [\n        {\n            period: \"2016 — 2019\",\n            locations: \"Muscat \\xb7 Goa \\xb7 Kolhapur\",\n            title: \"Hospitality Foundations & Taj Training\",\n            subtitle: \"Learning operational discipline where small mistakes compound immediately.\",\n            narrative: \"My foundational years were forged directly inside luxury hospitality. I studied Hospitality Management in Muscat before completing my formal degree in Goa. During my university years, I was selected as a Top 13 finalist for Femina Miss India (West Zone) — an intense detour that taught poise and calm under extreme public scrutiny. Shortly after graduating, I qualified as one of just 16 trainees nationwide for the prestigious Taj Management Training Programme. Returning to Kolhapur, I founded Mother India Cafe from scratch, learning real unit economics, kitchen margins, and daily operational ledger realities.\",\n            takeaways: [\n                \"Studied Hospitality Management in Muscat & Goa\",\n                \"Top 13 Finalist — Femina Miss India (West Zone)\",\n                \"Qualified for Taj Management Training Programme (1 of 16 pan-India)\",\n                \"Founder & Operator of Mother India Cafe (Kolhapur)\"\n            ]\n        },\n        {\n            period: \"2019 — 2021\",\n            locations: \"Goa \\xb7 Mumbai \\xb7 Pune\",\n            title: \"High-Pace Operations & The Strategic Pivot\",\n            subtitle: \"Navigating high-turnover dining, craft beverage distribution, and commercial pivots.\",\n            narrative: \"Venturing across Goa's hyper-competitive dining sector and regional distribution networks, I led on-ground operations and sales strategy for craft breweries and specialty F&B concepts. Working alongside leading hospitality operators including Passcode Hospitality, I saw firsthand that great food concepts frequently falter not on culinary craft, but because marketing promises and floor operations pull in opposite directions.\",\n            takeaways: [\n                \"Led regional on-ground sales for craft brewery ventures\",\n                \"Floor operations and brand consulting with Passcode Hospitality\",\n                \"Discovered the critical operational disconnect between agency marketing and kitchen realities\"\n            ]\n        },\n        {\n            period: \"2021 — 2024\",\n            locations: \"Ladakh \\xb7 Northern Frontier Theatres\",\n            title: \"Demanding Theatres & High-Altitude Operations\",\n            subtitle: \"Extreme field execution at 14,000+ feet in sub-zero Himalayan conditions.\",\n            narrative: \"In Ladakh, I directed high-altitude logistics and community documentation for the Indian Army under Operation Sadbhavana, including conceptualizing and executing project SHE across 8 remote border villages. Concurrently, I partnered with PictureTime to manage communications for mobile inflatable digital cinemas operating at 11,500+ feet in sub-zero winter temperatures.\",\n            takeaways: [\n                \"Field logistics and documentary production at 14,000+ ft for Indian Army\",\n                \"Conceptualized and executed project SHE across 8 border communities\",\n                \"Strategic communications for PictureTime inflatable cinema networks in Ladakh & IFFI Goa\"\n            ]\n        },\n        {\n            period: \"2024 — Present\",\n            locations: \"Pan-India Advisory\",\n            title: \"Ārohana Today: Strategy Meets Execution\",\n            subtitle: \"Bridging the gap between creative ambition and bottom-line commercial performance.\",\n            narrative: \"Ārohana was founded to provide the partner I always wished I had when running businesses: a consultancy that thinks like an owner, executes with creative finesse, and stays on the ground until systems actually produce verified results.\",\n            takeaways: [\n                \"Retainer partnerships spanning real estate, hospitality, defence, and healthcare\",\n                \"Zero vanity metrics — all engagements tied to commercial sustainability\",\n                \"End-to-end capabilities across digital growth, operations, and documentary cinema\"\n            ]\n        }\n    ],\n    team: [\n        {\n            prefix: \"Ms.\",\n            name: \"Madhura Hawal\",\n            role: \"Founder & Principal Consultant\",\n            focus: \"Commercial Strategy & Executive Advisory\",\n            bio: \"With credentials spanning luxury hospitality management in Muscat and Goa, Taj Management training, standalone cafe ownership, craft brewery distribution, and direct field logistics for Indian Army campaigns in Ladakh, Madhura leads every engagement with rigorous commercial discipline.\",\n            image: \"/images/about/team-ops-director.jpg\",\n            competencies: [\n                \"Commercial Strategy\",\n                \"Hospitality Operations\",\n                \"Military & Special Projects\"\n            ]\n        },\n        {\n            prefix: \"Mr.\",\n            name: \"Aditya Kulkarni\",\n            role: \"Creative Director & Brand Architect\",\n            focus: \"Brand Systems & Visual Direction\",\n            bio: \"Aditya directs identity systems, spatial design, and typography architecture across luxury, retail, and corporate sectors. His approach ensures that brand identity functions as an operational business asset that establishes distinct market authority.\",\n            image: \"/images/about/team-creative-director.jpg\",\n            competencies: [\n                \"Brand Architecture\",\n                \"Spatial Experience\",\n                \"Typography Systems\"\n            ]\n        },\n        {\n            prefix: \"Ms.\",\n            name: \"Tanvi Deshmukh\",\n            role: \"Head of Strategic Communications\",\n            focus: \"Positioning & Editorial Narrative\",\n            bio: \"Tanvi oversees brand narrative, institutional positioning, and corporate communications. Specializing in high-stakes briefs and legacy enterprise repositioning, she crafts clear, compelling brand messaging rooted in verified proof.\",\n            image: \"/images/about/team-strategy-lead.jpg\",\n            competencies: [\n                \"Brand Positioning\",\n                \"Editorial Architecture\",\n                \"Executive Communication\"\n            ]\n        },\n        {\n            prefix: \"Mr.\",\n            name: \"Arjun Patel\",\n            role: \"Lead Cinematographer & Film Director\",\n            focus: \"Film, Sound & Documentary Media\",\n            bio: \"Arjun directs documentary, film, and multimedia production for commercial campaigns and specialized institutional briefs. Having filmed extensively at 14,000+ feet in high-altitude Himalayan sectors under strict protocols, he brings cinematic precision to demanding environments.\",\n            image: \"/images/about/team-film-director.jpg\",\n            competencies: [\n                \"Cinematography\",\n                \"Field Direction\",\n                \"Post-Production Grading\"\n            ]\n        }\n    ]\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./data/about.ts\n");

